    {
      "service": "ts-travel-service",
      "fault_kind": "application_exception",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND span_name IN ('GET /api/v1/travelservice/routes/{tripId}','TravelController.getRouteByTripId') GROUP BY ALL",
          "claim": "Every GET /routes/{tripId} server span and its TravelController.getRouteByTripId child errored (about 2528 of 2528), with about 4ms of self-time."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, count(*) n FROM abnormal_logs WHERE service_name='ts-travel-service' AND level='SEVERE' AND message LIKE '%IllegalArgumentException: Invalid argument%' GROUP BY ALL",
          "claim": "ts-travel-service logs 2528 SEVERE dispatcher exceptions caused by java.lang.IllegalArgumentException: Invalid argument."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(avg(c.duration)/1e6,1) client_ms, sum(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-route-plan-service' AND s.service_name='ts-travel-service' GROUP BY ALL",
          "claim": "ts-route-plan-service calls to ts-travel-service take about 3452ms on the client side and 1340 of 1448 callee spans error (normal: 87ms, 0 errors)."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, count(*) n, round(avg(c.duration)/1e6,1) client_ms, round(avg(s.duration)/1e6,1) server_ms, sum(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-travel-plan-service' AND s.service_name='ts-route-plan-service' GROUP BY ALL",
          "claim": "ts-travel-plan-service calls to route-plan quickestRoute and cheapestRoute take about 50-55s with 42 errors each, versus ~0.3-0.5s normally."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(avg(duration)/1e6,1) avg_ms, round(max(duration)/1e6,1) max_ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "ts-travel-plan-service server spans reach 60s p95 with a 12s average in the incident window, against about 0.5s normally."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-food-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, count(*) n, round(avg(c.duration)/1e6,1) client_ms, round(avg(s.duration)/1e6,1) server_ms, sum(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) callee_err FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='ts-food-service' AND s.service_name='ts-travel-service' GROUP BY ALL",
          "claim": "ts-food-service calls to ts-travel-service take about 3943ms on the client side and all 1188 callee spans error (normal: 24ms, 0 errors)."
        }
      ]
    },
    {
      "from": "ts-food-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,1) avg_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-food-service' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "ts-food-service getAllFood server spans average 2687ms, with 73 of 111 failing with HTTP 500 from its travel call."
        }
      ]
    }
  ]
}
